          && hasSpellLineOfSight(world, {
            sourceId: last.id,
            targetId: c.id,
            sourcePos: last,
            targetPos: c,
            range: CHAIN_RADIUS,
            isBlocked,
          })) { best = c; bestD2 = dist2; }
