      spell,
      baseAmount: backlashDmg,
      type: 'electric',
      cause: 'spell:lightning:backlash',
      at: { x: apos.x, y: apos.y },
      salt: 0xBAC1,
    }));
    world.emit('spell:lightning:backlash', { actor, damage: backlashDmg });
  }

