    if (!fac || !areFactionsHostile(actorFaction, fac.key)) continue;
    const vit = world.get(id, Vitality);
    if (!vit || (vit.hp | 0) <= 0) continue;
    if (actorFaction === 'player' && !isTileVisible(p.x | 0, p.y | 0)) continue;
