    if (!srcNode) continue;
    used.add(id);
    world.emit('spell:bolt', {
      actor, targetId: id, spellId: spell.id,
      from: { x: srcNode.x, y: srcNode.y },
      to: { x: p.x, y: p.y },
      chainIndex: chain.length + arcIdx,
      wet: true,
    });
