import { hazardSystem } from "./hazardSystem.js";

export { spawnPlasmaCloud } from "../utils/spawnPlasmaCloud.js";

/**
 * Compatibility shim: plasma cloud ticking is now handled by hazardSystem.
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function plasmaCloudSystem(world) {
  hazardSystem(world);
}
// rules/data/callbacks/death.js
// Death callback context and shared factory functions for monster death hooks.

import { spawnPlasmaCloud } from "../../utils/spawnPlasmaCloud.js";
import { CentipedeSegment } from "../../components/CentipedeSegment.js";
import { Brain } from "../../components/Brain.js";
import { AggroState, AGGRO_LEVELS, SEARCH_TURNS_HUNTING_GRACE } from "../../components/AggroState.js";
import { SoundEmitter } from "../../components/SoundEmitter.js";
import { Wounds } from "../../components/Wounds.js";
import { Position } from "../../components/Position.js";
import { spawnHazard } from "../../utils/hazardSpawn.js";

/**
 * Context passed to monster death hook callbacks.
 * Provides emit(), cancel(), and hazard helper methods.
 */
export class DeathCallbackContext {
  /**
   * @param {any} world
   * @param {{
   *   deadId: number,
   *   killer: number,
   *   cause: string,
   *   identity: string,
   *   pos: { x:number, y:number } | null,
   * }} frame
   */
  constructor(world, frame) {
    this.world = world;
    this._frame = frame;
    this._cancelled = false;
    this._cancelReason = null;
  }

  get deadId() { return this._frame.deadId | 0; }
  get killer() { return this._frame.killer | 0; }
  get cause() { return String(this._frame.cause || ""); }
  get identity() { return String(this._frame.identity || ""); }
  get pos() { return this._frame.pos || null; }

  get cancelled() { return this._cancelled; }
  get cancelReason() { return this._cancelReason; }

  /**
   * @param {unknown} reason
   */
  cancel(reason) {
    this._cancelled = true;
    this._cancelReason = typeof reason === "string"
      ? { code: reason, message: reason }
      : reason || { code: "CANCELLED", message: "Cancelled" };
  }

  /** @param {string} eventName @param {any} payload */
  emit(eventName, payload) {
    this.world.emit(eventName, payload);
  }

  /**
   * @param {{ turnsLeft?:number, radius?:number, damage?:number, sourceId?:number, sourceKind?:string }} [params]
   */
  spawnPlasmaCloud(params = {}) {
    const pos = this.pos;
    if (!pos) return 0;
    const sourceKind = String(params.sourceKind || this.identity || "");
    const sourceId = Number.isFinite(params.sourceId)
      ? (params.sourceId | 0)
      : (this.deadId | 0);
    return spawnPlasmaCloud(this.world, {
      x: pos.x | 0,
      y: pos.y | 0,
      turnsLeft: params.turnsLeft,
      radius: params.radius,
      damage: params.damage,
      sourceId,
      sourceKind,
    });
  }
}

/**
 * Spawn a plasma cloud centered on the dead monster's tile.
 * @param {{ turnsLeft?:number, radius?:number, damage?:number, sourceKind?:string }} [params]
 */
export function spawnPlasmaCloudOnDeath(params = {}) {
  const config = (params && typeof params === "object") ? { ...params } : {};
  return (ctx) => {
    if (!ctx || typeof ctx.spawnPlasmaCloud !== "function") return;
    ctx.spawnPlasmaCloud(config);
  };
}

/**
 * Spawn a small floor-fire puff at death location.
 * Intended for low-yield deaths like burning vermin.
 *
 * @param {{
 *   turnsLeft?: number,
 *   tickDamage?: number,
 *   radius?: number,
 *   identity?: string,
 *   name?: string,
 }} [params]
 */
export function spawnFirePuffOnDeath(params = {}) {
  const cfg = (params && typeof params === "object") ? { ...params } : {};
  return (ctx) => {
    if (!ctx?.pos) return;
    const x = ctx.pos.x | 0;
    const y = ctx.pos.y | 0;
    spawnHazard(ctx.world, {
      x,
      y,
      kind: "fire",
      medium: "floor",
      turnsLeft: Math.max(1, Number(cfg.turnsLeft ?? 2) | 0),
      radius: Math.max(0, Number(cfg.radius ?? 0) | 0),
      tickDamage: Math.max(0, Number(cfg.tickDamage ?? 1) | 0),
      damageType: "fire",
      cause: "monster:death:fire_puff",
      sourceId: ctx.deadId | 0,
      sourceKind: String(ctx.identity || "flaming_bat"),
      identity: String(cfg.identity || "flame_puff"),
      name: String(cfg.name || "Flame Puff"),
    });
    ctx.world.emit("monster:death:fire_puff", {
      id: ctx.deadId | 0,
      at: { x, y },
    });
  };
}

// ── Gas spore explosion ──────────────────────────────────────────────

/**
 * Spawn a large fire explosion at death location — gas spore detonation.
 * Creates a multi-tile fire hazard and emits a dedicated event for VFX.
 *
 * @param {{
 *   turnsLeft?: number,
// rules/data/monsters.js
// Central monster definitions. Each entry feeds into pickMonster() for spawning
// and the Monster archetype for ECS creation.
//
// All combat behavior lives here on the monster it governs — callbacks are
// plain (ctx) => void functions invoked via runCallbackList.
import {
  statusEffectOnHit,
  selfBuffOnHit,
  drainOnHit,
  bonusDamageOnBeforeHit,
  bonusDamageIfTargetAfflicted,
  drainAndWeakenOnHit,
  healOnDamaged,
  retaliateOnDamaged,
  statusEffectOnDamaged,
  phaseOutOnDamaged,
  sandBurrowOnDamaged,
  mindflayerBlastOnHit,
  corrodeEquipmentOnHit,
  stealAndBlinkOnHit,
  typedDamageOnHit,
  spillLootAndShortBlinkOnDamaged,
  burrowAndDieOnHit,
  slimedOnHit,
} from "./callbacks/combat.js";
import { selfThrowNearTargetOnSeen, gazeOnLOS, fireBreathLineOnLOS, castSpellOnLOS } from "./callbacks/ai.js";
import { spawnPlasmaCloudOnDeath, centipedeSplitOnDeath, spawnFirePuffOnDeath, gasSporeExplodeOnDeath } from "./callbacks/death.js";

export const MONSTERS = [
];


// Global monster vitality scalar used by all depth-scaled spawn pathways.
// Tune this to raise/lower overall monster durability without per-monster edits.
export const MONSTER_HP_SCALAR = 1.0;

/** Lookup helpers */
const _byId = new Map(MONSTERS.map(m => [m.id, m]));
const _byTier = [];
for (const m of MONSTERS) {
  if (!m.rare && !m.disabled) (_byTier[m.tier] ??= []).push(m);
}

/** Genocide registry — tracks monster IDs permanently removed from the game. */
const _genocided = new Set();

/** @param {string} id */
export function addGenocide(id) { _genocided.add(id); }

/** @param {string} id @returns {boolean} */
export function isGenocided(id) { return _genocided.has(id); }

/** @returns {string[]} */
export function getAllGenocided() { return [..._genocided]; }

export function clearGenocides() { _genocided.clear(); }

/** @param {number} tier @returns {MonsterDef[]} */
export function getMonstersByTier(tier) {
  const pool = _byTier[Math.min(tier, _byTier.length - 1)] || _byTier[_byTier.length - 1];
  if (_genocided.size === 0) return pool;
  return pool.filter(m => !_genocided.has(m.id));
}

/** @param {string} id @returns {MonsterDef|null} */
export function getMonster(id) {
  return _byId.get(id) || null;
}

/**
 * Resolve scaled monster max HP at a given dungeon depth.
 * @param {string|MonsterDef|null|undefined} monster
 * @param {number} depth
 * @returns {number}
 */
export function resolveMonsterMaxHp(monster, depth = 1) {
  const def = typeof monster === "string" ? getMonster(monster) : (monster || null);
  if (!def) return 1;
  const d = Math.max(1, Number(depth || 1) | 0);
  const baseHp = Number(def.baseHp || 1);
  const hpPerLevel = Number(def.hpPerLevel || 0);
  const unscaled = baseHp + d * hpPerLevel;
  return Math.max(1, Math.floor(unscaled * MONSTER_HP_SCALAR));
}

/** @returns {string[]} */
export function listAllMonsterIds() {
  return [..._byId.keys()].sort();
}

/** @returns {MonsterDef[]} */
export function getAllMonsters() {
  return [..._byId.values()];
}

/** @param {MonsterDef} def @returns {string} loot table ID */
export function getMonsterLootTable(def) {
  if (def.lootTable) return def.lootTable;
  const tags = def.tags || [];
  // Tag priority: caster > venomous > beast > humanoid > undead > tier fallback
  if (tags.includes('caster'))   return 'drop:caster';
  if (tags.includes('venomous')) return 'drop:venomous';
  if (tags.includes('beast'))    return 'drop:beast';
  if (tags.includes('humanoid')) return 'drop:humanoid';
  if (tags.includes('undead'))   return 'drop:undead';
  return `drop:tier${def.tier}`;
}

/**
 * Check whether a monster (by id) carries a given tag.
 * @param {string} monsterId
 * @param {string} tag
 * @returns {boolean}
 */
export function monsterHasTag(monsterId, tag) {
  const def = _byId.get(monsterId);
  if (!def || !Array.isArray(def.tags)) return false;
  return def.tags.includes(tag);
}

